import{z as l,x as A,o as B,c as d,q as i,j as o,D as e,d as E,s as r,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"脱敏与令牌化","description":"","frontmatter":{"title":"脱敏与令牌化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/data-masking-tokenization.md","filePath":"cs/data-masking-tokenization.md","lastUpdated":1791413859000}'),p={name:"cs/data-masking-tokenization.md"};function C(D,a,h,m,F,c){const n=A("Mermaid");return B(),d("div",null,[a[2]||(a[2]=i('<h1 id="脱敏与令牌化" tabindex="-1">脱敏与令牌化 <a class="header-anchor" href="#脱敏与令牌化" aria-label="Permalink to &quot;脱敏与令牌化&quot;">​</a></h1><div class="epigraph"><p>脱敏把生产数据变成测试可用的形状；令牌化用随机替代值换掉主键，真值放进保险库。二者减少明文扩散，但不能把弱访问控制补成强。</p><footer>—— 据 NIST 对去标识化的讨论；PCI DSS 对令牌化的实践陈述；对照 GDPR 最小化</footer></div><p>上一课<a href="/cs/gdpr-technical">GDPR</a>要最小化。缺口是<strong>工程手段</strong>：掩码、令牌、保险库。本课分工，不把脱敏当 DP。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>测试环境拷生产库是最常见的明文扩散：开发机、笔记本、外包各落一份副本，数据一出受控库，访问控制与审计跟着失效。子集抽取比全量脱敏便宜，但外键要在切片内保持一致，否则测试数据自相矛盾。缺口：格式保留 vs 随机令牌、保险库 ACL、不可逆哈希盐（回口令课）。</p><p><span class="marginnote">令牌化就是&quot;用收据代替原件&quot;：系统里流通的是随机代币（收据），原件锁进保险库，需要真值时凭收据去兑。收据丢了无所谓，保险库才是唯一要重兵把守的地方。</span></p><h3 id="可逆" tabindex="-1">可逆 <a class="header-anchor" href="#可逆" aria-label="Permalink to &quot;可逆&quot;">​</a></h3><p>可逆令牌化的保险库是新 TCB，等于又一个密钥管理系统：主密钥在 HSM 或密钥服务，映射表自身要加密、审计、按用途限权；保险库打穿等价全部明文失守。静态脱敏在数据出口一次性变换；动态脱敏在查询路径按角色实时重写，代价是查询延迟与策略维护面。</p><p><span class="marginnote">PCI DSS 令牌化指南。MPC 下一课让计算不必集中明文。确定性变换泄露相等性：同值同码即可做频率分析；FPE（NIST SP 800-38G）保格式仍属确定性替换。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型按用途：测试要保形——类型、长度、引用完整；令牌化要保可逆与可联结。PAN 令牌常保留 BIN 与尾四位，校验位仍过 Luhn。跨环境联结用带密钥的 HMAC-SHA-256 替代裸哈希：无钥者建不了字典反查。令牌用密码学随机（128 位 UUID 或加密计数器），不用可枚举序号——枚举令牌让越界方按序反推总量。不可逆脱敏破坏联结与统计性质，聚合口径要事先定。下一课 MPC 应用。</p><p><span class="marginnote">数字实例：卡号 4111 1111 1111 1111 令牌化后常形如 4111 0000 1234 5678——保留前 6 位 BIN 与末 4 位，中间随机；老系统照常识别卡组织、Luhn 校验位照样通过，但真卡号已不在。</span></p>',13)),(B(),o(s,null,{default:e(()=>[r(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PII%5B%22%E6%98%8E%E6%96%87%E6%A0%87%E8%AF%86%22%5D%20--%3E%20TOK%5B%22%E4%BB%A4%E7%89%8C%22%5D%0A%20%20TOK%20--%3E%20VAULT%5B%22%E4%BF%9D%E9%99%A9%E5%BA%93%E6%98%A0%E5%B0%84%22%5D%0A%20%20MASK%5B%22%E6%B5%8B%E8%AF%95%E8%84%B1%E6%95%8F%22%5D%20--%3E%20SHAPE%5B%22%E4%BF%9D%E7%95%99%E6%A0%BC%E5%BC%8F%E6%97%A0%E7%9C%9F%E5%80%BC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("机制是缩小敏感数据的暴露集：真值副本从 N 份降到 1 份（保险库），其余位置只有令牌，越界数据的价值随可联结性下降。失败模式：可逆性失控（保险库权限过宽）、确定性泄露相等性、脱敏字段的组合仍可再识别——回到 "),t("a",{href:"/cs/k-anonymity"},"k-匿名"),E(" 的维度攻击。与差分隐私的分界：脱敏是集合缩小，DP 对查询结果本身加噪并给出 \\(\\varepsilon\\) 保证；GDPR 下假名化数据仍是个人数据，匿名化才是出列，判例从严。MPC 下一课连计算都不集中。")],-1)),(B(),o(s,null,{default:e(()=>[r(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%90%AB%E6%95%8F%E6%84%9F%E5%AD%97%E6%AE%B5%E7%9A%84%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20Q%7B%22%E6%8B%BF%E5%8E%BB%E5%81%9A%E4%BB%80%E4%B9%88%22%7D%0A%20%20Q%20--%3E%7C%22%E5%BC%80%E5%8F%91%E6%B5%8B%E8%AF%95%22%7C%20S%5B%22%E9%9D%99%E6%80%81%E8%84%B1%E6%95%8F%EF%BC%9A%E5%87%BA%E5%8F%A3%E4%B8%80%E6%AC%A1%E6%80%A7%E5%8F%98%E5%BD%A2%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9F%A5%E8%AF%A2%E5%B1%95%E7%A4%BA%22%7C%20DY%5B%22%E5%8A%A8%E6%80%81%E8%84%B1%E6%95%8F%EF%BC%9A%E6%8C%89%E8%A7%92%E8%89%B2%E5%AE%9E%E6%97%B6%E9%87%8D%E5%86%99%22%5D%0A%20%20Q%20--%3E%7C%22%E7%94%9F%E4%BA%A7%E4%BB%8D%E9%9C%80%E8%BF%98%E5%8E%9F%22%7C%20T%5B%22%E4%BB%A4%E7%89%8C%E5%8C%96%EF%BC%9A%E7%9C%9F%E5%80%BC%E8%BF%9B%E4%BF%9D%E9%99%A9%E5%BA%93%22%5D%0A%20%20T%20--%3E%20V%5B%22%E4%BF%9D%E9%99%A9%E5%BA%93%E5%8D%B3%E6%96%B0%20TCB%EF%BC%8C%E6%8C%89%E7%94%A8%E9%80%94%E9%99%90%E6%9D%83%22%5D%0A%20%20S%20--%3E%20E%5B%22%E6%9A%B4%E9%9C%B2%E9%9B%86%E7%BC%A9%E5%B0%8F%EF%BC%8C%E4%BD%86%E5%AD%97%E6%AE%B5%E7%BB%84%E5%90%88%E4%BB%8D%E5%8F%AF%E8%83%BD%E5%86%8D%E8%AF%86%E5%88%AB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：以为&quot;每列都脱敏了就安全&quot;。经典结果是邮编＋出生日期＋性别三列组合，能唯一识别约 87% 的美国人——单列看着无害的字段凑在一起，就可能指回具体的一个人。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写再识别。不把脱敏报表当成匿名化结论。MPC 应用下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>法律要最小化；令牌化减少明文副本。</li><li>保险库是新 TCB。</li><li>脱敏不是差分隐私。</li><li>下一课 MPC 应用。</li><li>出处：PCI DSS 令牌化；NIST 去标识化讨论。</li></ul>',5))])}const T=l(p,[["render",C]]);export{P as __pageData,T as default};
